+test("consume order: earliest expiry, then received first, then lower id; no expiry last", () => {
+  const store = fresh();
+  const add = (id, receivedOn, expires) =>
+    store.data.batches.push({ id, itemId: 3, lot: `T-${id}`, qty: 1, receivedOn, expires, location: "fridge" });
+  add(100, "2026-10-01", null);
+  add(101, "2026-10-25", "2026-11-05");
+  add(103, "2026-10-21", "2026-11-05");
+  add(102, "2026-10-21", "2026-11-05");
+  const used = consume(store, 3, onHand(store, 3), { at });
+  assert.deepEqual(used.map((u) => u.batchId), [102, 103, 101, 5, 100]);
